<?php
require_once __DIR__.'/../../includes/staff/feature-tools.php';require_permission('portal.manage');verify_csrf();$pdo=staff_db();feature_table($pdo,'customer_users');$magic='';
if($_SERVER['REQUEST_METHOD']==='POST'){$cid=fint('customer_id');$c=db_one($pdo,'SELECT * FROM customers WHERE id=?',[$cid]);if(!$c){flash('error','Customer not found.');staff_redirect('staff/admin/customer-portal-access.php');}$email=fpost('email')?:($c['email']??'');if(!$email){flash('error','An email address is required for portal access.');staff_redirect('staff/admin/customer-portal-access.php');}$u=db_one($pdo,'SELECT * FROM customer_users WHERE customer_id=?',[$cid]);if(!$u){$pdo->prepare('INSERT INTO customer_users(customer_id,email,is_active) VALUES(?,?,1)')->execute([$cid,$email]);$uid=(int)$pdo->lastInsertId();}else{$uid=(int)$u['id'];$pdo->prepare('UPDATE customer_users SET email=?,is_active=1 WHERE id=?')->execute([$email,$uid]);}$raw=bin2hex(random_bytes(24));$hash=hash('sha256',$raw);$pdo->prepare("INSERT INTO customer_portal_tokens(customer_user_id,token_hash,token_type,expires_at) VALUES(?,?,'magic_login',DATE_ADD(NOW(),INTERVAL 30 MINUTE))")->execute([$uid,$hash]);$magic=ideare_root_url('pages/customer-portal.php?token='.urlencode($raw));}
$customers=customer_options($pdo);$users=db_rows($pdo,'SELECT u.*,c.customer_code,c.name customer_name FROM customer_users u JOIN customers c ON c.id=u.customer_id ORDER BY u.updated_at DESC');$pageTitle='Customer Portal Access';require __DIR__.'/../../includes/staff/header.php';module_head('Customer Portal','Portal Access','Provision a customer account and generate a short-lived secure login link.');?>
<?php if($magic):?><section class="staff-panel"><h2>Magic login link created</h2><p>This link expires in 30 minutes and can be used once to start a portal session.</p><input value="<?=h($magic)?>" readonly onclick="this.select()"><p><a class="btn primary" target="_blank" href="<?=h($magic)?>">Open portal link</a></p></section><?php endif?>
<section class="staff-panel"><h2>Create / refresh portal access</h2><form method="post" class="mini-form"><?=csrf_field()?><label>Customer<select name="customer_id" required><option value="">Choose...</option><?php foreach($customers as $c):?><option value="<?=$c['id']?>"><?=h($c['customer_code'].' · '.$c['name'])?></option><?php endforeach?></select></label><label>Email<input type="email" name="email" placeholder="Uses customer email if blank"></label><button class="btn primary">Generate login link</button></form></section>
<section class="staff-panel table-panel"><table><thead><tr><th>Customer</th><th>Email</th><th>Active</th><th>Last login</th></tr></thead><tbody><?php foreach($users as $u):?><tr><td><b><?=h($u['customer_name'])?></b><small><?=h($u['customer_code'])?></small></td><td><?=h($u['email'])?></td><td><?=$u['is_active']?'Yes':'No'?></td><td><?=h($u['last_login_at']?:'Never')?></td></tr><?php endforeach?></tbody></table></section><?php module_end();require __DIR__.'/../../includes/staff/footer.php';?>